using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;using SolicitudIT_Isertec.Data;using SolicitudIT_Isertec.Models;using SolicitudIT_Isertec.Services;
namespace SolicitudIT_Isertec.Controllers;[Authorize(Roles="admin")]public class AdminController:Controller{readonly AppDbContext db;public AdminController(AppDbContext db)=>this.db=db;public async Task<IActionResult> Index(){return View(new AdminVm{Usuarios=await db.Usuarios.OrderBy(x=>x.Nombre).ToListAsync(),Equipos=await db.Equipos.Include(x=>x.Usuario).OrderBy(x=>x.Codigo).ToListAsync(),Categorias=await db.Categorias.OrderBy(x=>x.Nombre).ToListAsync()});}
[HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult> UserSave(int? id,string nombre,string apellido,string usuario,string email,string password,Rol rol,bool activo=true){Usuario u=id.HasValue?await db.Usuarios.FindAsync(id):new Usuario();if(u==null)return NotFound();u.Nombre=nombre;u.Apellido=apellido;u.UsuarioLogin=usuario;u.Email=email;u.Rol=rol;u.Activo=activo;if(!string.IsNullOrWhiteSpace(password))u.Password=BCrypt.Net.BCrypt.HashPassword(password);if(!id.HasValue)db.Usuarios.Add(u);await db.SaveChangesAsync();return RedirectToAction(nameof(Index));}
[HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult> EquipmentSave(int? id,string codigo,string tipo,string? marca,string? modelo,string? numeroSerie,int? usuarioId,string? ubicacion,EstadoEquipo estado,string? observaciones){var e=id.HasValue?await db.Equipos.FindAsync(id):new Equipo();if(e==null)return NotFound();e.Codigo=codigo;e.Tipo=tipo;e.Marca=marca;e.Modelo=modelo;e.NumeroSerie=numeroSerie;e.UsuarioId=usuarioId;e.Ubicacion=ubicacion;e.Estado=estado;e.Observaciones=observaciones;if(!id.HasValue)db.Equipos.Add(e);await db.SaveChangesAsync();return RedirectToAction(nameof(Index));}}
public class AdminVm{public List<Usuario> Usuarios{get;set;}=new();public List<Equipo> Equipos{get;set;}=new();public List<Categoria> Categorias{get;set;}=new();}
